response:
{
  "id": "tang-poetry-imagery-emotion",
  "title": "唐诗中的意象与情感",
  "subtitle": "从物象到心象的解码",
  "language": "zh-CN",
  "audience": "高中语文",
  "theme": "soft-editorial",
  "tutor": {
    "suggestions": [
      "为什么唐诗中写'月'多半与思乡有关，而不是其他情感？",
      "如果诗人把'落花'换成'落叶'，情感基调会有什么变化？",
      "意象是否可以脱离全诗语境独立存在？请举例说明。",
      "现代流行歌词中有没有类似唐诗意象的表达？"
    ],
    "kb": [
      {
        "pattern": "意象|客观物象",
        "answer": "融入了主观情感的客观物象，即**意**（情感）+**象**（物象）。如'月'本是天体，在诗中却承载了思乡之**意**。"
      },
      {
        "pattern": "借景抒情|寓情于景",
        "answer": "不直接说出情感，而是将情感寄托在特定意象中，让读者通过意象自行体会。如*借*满地'黄花'抒发孤寂。"
      },
      {
        "pattern": "柳|折柳",
        "answer": "谐音'留'，古人有折柳送别的习俗，故唐诗中'柳'多指代送别、留恋，如*渭城朝雨浥轻尘，客舍青青柳色新*。"
      },
      {
        "pattern": "孤蓬|飞蓬",
        "answer": "随风飘转的蓬草，唐诗中常用来比喻漂泊无依的游子，如*此地一为别，孤蓬万里征*。"
      },
      {
        "pattern": "意象组合|意象群",
        "answer": "单个意象往往不足以表达复杂情感，诗人会将多个意象并置，形成具有张力的画面，如*鸡声茅店月，人迹板桥霜*全用名词意象叠加。"
      }
    ]
  },
  "scenes": [
    {
      "id": "cover",
      "kind": "hero",
      "notes": "开场先不定义概念，直接抛出'床前明月光'，问学生为什么李白看到月亮就想家，引出物象与情感的绑定关系。",
      "blocks": [
        {
          "id": "b_cover",
          "type": "hero",
          "intent": "封面：标题+一句副题"
        }
      ]
    },
    {
      "id": "concept",
      "kind": "content",
      "eyebrow": "核心概念",
      "headline": "物象如何成为意象",
      "lead": "意象是打上主观情感烙印的客观物象。",
      "notes": "重点区分'物象'（纯物理存在）和'意象'（情感载体）。比如'水'是物象，'一江春水'就是承载愁绪的意象。学生常犯的误区是把意象当成单纯的修辞手法。",
      "blocks": [
        {
          "id": "b1",
          "type": "compare",
          "intent": "对比纯客观物象与注入情感的意象，明确'意'与'象'的融合"
        }
      ]
    },
    {
      "id": "anchor",
      "kind": "content",
      "eyebrow": "难点突破",
      "headline": "意象的生成：以“柳”为例",
      "lead": "同一物象因文化习俗与语境不同，可生成不同情感指向的意象。",
      "notes": "这是全课最难的机制：客观物象如何获得约定俗成的情感含义。用'柳'做锚点：第一步，柳条随风如挥手（视觉）；第二步，'柳'谐音'留'（听觉/习俗）；第三步，折柳赠别（行为固化）。反例：贺知章'万条垂下绿丝绦'则取其生机，无送别之意。",
      "blocks": [
        {
          "id": "b2",
          "type": "flow",
          "intent": "一步步拆解'柳'如何从植物学对象变成送别意象，并展示反例"
        }
      ]
    },
    {
      "id": "group1",
      "kind": "content",
      "eyebrow": "经典意象群",
      "headline": "月与雁：空间阻隔的遥相呼应",
      "lead": "天空中的高远意象常用来跨越空间，寄托思乡与怀远。",
      "notes": "月：张九龄'海上生明月，天涯共此时'——空间跨度极大，用月光连接两地。雁：大雁秋去春来，有信使之意，杜甫'孤雁不饮啄，飞鸣声念群'——以孤雁写乱离中骨肉分离。提醒学生注意，雁多在秋景出现，自带悲凉底色。",
      "blocks": [
        {
          "id": "b3",
          "type": "list",
          "intent": "列举'月'与'雁'在具体诗句中的情感指向，带出原诗与数据"
        }
      ]
    },
    {
      "id": "group2",
      "kind": "content",
      "eyebrow": "经典意象群",
      "headline": "落花与流水：时间流逝的不可逆转",
      "lead": "地面与水面的衰败意象常用来映射时光易逝与生命凋零。",
      "notes": "落花：从孟浩然'花落知多少'的淡淡惋惜，到李贺'桃花流水窅然去'的绝望。流水：李白'抽刀断水水更流'，水的不可截断性对应愁的无法消除。两者叠加就是'流水落花春去也，天上人间'的极致悲亡。",
      "blocks": [
        {
          "id": "b4",
          "type": "grid",
          "intent": "并置落花与流水的诗句切片，展示伤春悲秋的具象表达"
        }
      ]
    },
    {
      "id": "combo",
      "kind": "content",
      "eyebrow": "意象的组合",
      "headline": "名词并置：无需动词的情感张力",
      "lead": "意象的直接叠加能产生远超单点的情感浓度。",
      "notes": "温庭筠'鸡声茅店月，人迹板桥霜'没有一个动词，却把早行之苦写绝了。六个意象（鸡声、茅店、月、人迹、板桥、霜）像电影蒙太奇一样拼接，残月当空、寒霜未退，行人的孤寂跃然纸上。这是意象组合的高级形态。",
      "blocks": [
        {
          "id": "b5",
          "type": "pullquote",
          "intent": "以温庭筠诗句为例，展示纯名词意象叠加的蒙太奇效果"
        }
      ]
    },
    {
      "id": "quiz",
      "kind": "quiz",
      "headline": "随堂检验",
      "notes": "题目设计要避开死记硬背，给出一句没学过的诗，让学生判断核心意象及情感。比如'落叶他乡树，寒灯独夜人'，问'寒灯'指向何种心境。",
      "blocks": [
        {
          "id": "bq",
          "type": "quiz",
          "intent": "考察学生对意象与情感对应关系的判断，以及意象组合效果的分析"
        }
      ]
    },
    {
      "id": "ending",
      "kind": "hero",
      "notes": "收尾再次呼应封面，强调读懂意象就是拿到了唐诗的解码器。不要把意象当成僵化的符号，它是古人情感与自然万物最精妙的共振。",
      "blocks": [
        {
          "id": "b_ending",
          "type": "hero",
          "intent": "收尾：总结意象是唐诗的情感密码"
        }
      ]
    }
  ]
